              className: 'dnb-primary-btn',
              style: { height: 28, padding: '0 12px', fontSize: 11.5, flexShrink: 0 },
              disabled: view.archiveOrganizing,
              onClick: () => void requestOrganizeArchives({ vaultScope: targetScope }),
