                  style: { height: 28, borderRadius: 99, padding: '0 11px', fontSize: 11.5 },
                  placeholder: '筛选沉淀经验标题、类别、关键词…',
                  value: view.archiveQuery || '',
                  onChange: e => patch({ archiveQuery: e.target.value }),
